# ============================================================== 몬스터
# 수치는 '배율'. 실제 수치 = 레벨 기반 기본치 x 배율 (엔진 monster_stats 참고)
def _m(name, art, hp=1.0, atk=1.0, df=1.0, spd=1.0, exp=1.0, gold=1.0, special=None, chance=0.0, drops=(), desc=""):
    return dict(name=name, art=art, hp=hp, atk=atk, df=df, spd=spd, exp=exp, gold=gold,
                special=special, chance=chance, drops=list(drops), desc=desc)


