# 시즌 1 「초록불을 찾아서」: 챕터 12개 = 지역 12개. 챕터 n 이 열려야 지역 n 에 들어갈 수 있다.
#   - 앞의 fast 개 챕터는 바로 열린다 (첫 주: 진행만 하면 다음 챕터)
#   - 그다음부터는 스토리 시작일 기준 every 일마다 하나씩 열린다 (그리고 앞 챕터를 끝내야 시작)
#   - 챕터 = 프롤로그(대화) → 미션(필수 3 + 보너스 1) → 챕터 보스(대화 + 전투) → 에필로그 + 보상
# 대사: (말하는 이, 문장). 말하는 이: NPCS 의 키 / "pet"(내 펫) / "boss"(챕터 보스) / "narr"(해설). {name} = 펫 이름
#   "pet:sad" 처럼 : 뒤에 표정(FACES 키)을 붙이면 대화 속 펫 얼굴이 바뀐다. 펫 대사는 PET_LINES 에서 성격마다 바뀐다
