# ============================================================== 챕터 보스 기믹 (v5)
# 보스가 큰 기술을 '예고'하면 잠깐 싸움이 멈추고 대응 창이 열린다. 맞게 대응하면 good, 틀리거나 못 하면 bad.
# 지켜보는 사람은 키로 고르고, 안 보는 사람(자동)은 auto 확률로 맞힌다 → 방치해도 결국 깨고, 지켜보면 더 쉽다.
#   every: N라운드마다 예고 (첫 예고는 2라운드 뒤) · every2: 2페이즈에서의 간격
#   warn: 예고 대사 ({agenda} {clue} {q} {n} 자리) · hint: 예고 아래 작은 글씨
#   opts: [(키, 선택지)] · ans: 정답 키 (quiz · clue 는 문제마다)
#   good / bad 효과 키:
#     stun n(보스 멈춤) · dmg x(펫 강공격 배율) · pct x(보스 최대 HP 비율 피해) · def_down n(보스 방어 -35% n턴)
#     heal x(펫 HP 비율) · mp x(펫 MP 비율)
#     hit x(보스 즉시 공격 배율) · sleep n · pstun n(펫 행동 불가) · confuse n · poison n · wipe(펫 버프 삭제)
#     boss_heal x · boss_atk x(보스 공격력 +x, 누적) · mp_drain x
#   ok / ng: 결과 문구 (ng 는 {키: 문구} 로 선택지마다 달리 쓸 수 있다)
#   meter: 보스 고유 계기 — label · start · unit · win(맞히면 +) · lose(틀리면 +) · auto(라운드마다 +) · reset(맞히면 0)
#          goal/full/full_text: 계기가 goal 에 닿으면 한 번 full 효과 · atk_per: 계기 1당 보스 공격력 +
#   auto: 자동 대응 성공 확률 (패배한 만큼 '회고'로 +)
#   tune: (HP 배율, 공격력 배율) 챕터마다 손질 — tools/tq_sim.py --duel 로 '안 봐도 50~70% · 지켜보면 90%+' 에 맞춘 값
GIM_WINDOW = dict(watch=8.0, away=2.5)     # 대응 창 (초): 방금 키를 누른 사람 / 자리 비운 사람
GIM_RETRO = dict(hp=0.08, atk=0.04, auto=0.08, cap=5)   # 패배 1번마다 (최대 5번) 보스 HP · 공격력 ↓, 자동 대응 ↑
